class Solution {
public:
    int m, n;
    vector<vector<int>> atlantic, pacific;
	vector<vector<int>> ans;    
    void dfs(vector<vector<int>> &heights,vector<vector<int>> &vis,int i,int j)
    {        
        if(vis[i][j]) 
            return;
        vis[i][j] = 1;
        if(atlantic[i][j] && pacific[i][j]) 
            ans.push_back(vector<int>{i, j});    
        if(i + 1 <  m and heights[i + 1][j] >= heights[i][j]) 
            dfs(heights, vis, i + 1, j); 
        if(i - 1 >= 0 and heights[i - 1][j] >= heights[i][j]) 
            dfs(heights, vis, i - 1, j);
        if(j + 1 <  n and heights[i][j + 1] >= heights[i][j]) 
            dfs(heights, vis, i, j + 1); 
        if(j - 1 >= 0 and heights[i][j - 1] >= heights[i][j]) 
            dfs(heights, vis, i, j - 1);
    }
    vector<vector<int> > pacificAtlantic(vector<vector<int>>& heights) 
    {
        m=heights.size();
        n=heights[0].size();
        atlantic = pacific = vector<vector<int> >(m, vector<int>(n, false));
        for(int i = 0; i < m; i++) 
        {
            dfs(heights, pacific, i, 0);
            dfs(heights, atlantic, i, n - 1);   
        }
        for(int i = 0; i < n; i++)
        {
            dfs(heights, pacific, 0, i);
            dfs(heights, atlantic, m - 1, i);
        }
        return ans;
    }
};

class Solution(object):
    def pacificAtlantic(self, heights):
        """
        :type heights: List[List[int]]
        :rtype: List[List[int]]
        """
        m, n = len(heights), len(heights[0])

        def bfs(s):
            q = deque(s)
            vis = set(s)
            while q:
                cur_x, cur_y = q.popleft()
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    new_x = cur_x + dx
                    new_y = cur_y + dy
                    if not (0 <= new_x < m and 0 <= new_y < n):
                        continue
                    if (new_x, new_y) in vis:
                        continue
                    if heights[new_x][new_y] >= heights[cur_x][cur_y]:
                        q.append((new_x, new_y))
                        vis.add((new_x, new_y))
            return vis

        pacific = [(0, i) for i in range(n)] + [(i, 0) for i in range(1, m)]
        atlantic = [(m - 1, i) for i in range(n)] + [(i, n - 1) for i in range(m - 1)]
        return list(map(list, bfs(pacific) & bfs(atlantic)))
